window.QUIZ_BANK['testng'] = (window.QUIZ_BANK['testng']||[]).concat([
{id:1871,topic:'testng',difficulty:'beginner',question:'What is TestNG?',options:['A Python testing framework','A Java testing framework inspired by JUnit and NUnit, designed to cover unit, functional, integration, and end-to-end testing','A JavaScript test runner','A build tool'],answer:1,explanation:'TestNG (Test Next Generation) is a testing framework created by Cédric Beust. It extends JUnit\'s capabilities with features like annotations, grouping, sequencing, parameterization, and parallel execution.'},
{id:1872,topic:'testng',difficulty:'beginner',question:'What annotation marks a test method in TestNG?',options:['@Test','@TestMethod','@RunWith','@Execute'],answer:0,explanation:'@Test is the primary annotation that marks a method as a test method in TestNG. The test runner will execute any method annotated with @Test.'},
{id:1873,topic:'testng',difficulty:'beginner',question:'What does `@BeforeMethod` do in TestNG?',options:['Runs before each test class','Runs before each @Test method in a test class','Runs before the entire suite','Runs before each test group'],answer:1,explanation:'@BeforeMethod annotates a method that will run before EACH @Test method in the class. Typically used for test setup: creating objects, setting initial state, etc.'},
{id:1874,topic:'testng',difficulty:'beginner',question:'What does `@AfterMethod` do in TestNG?',options:['Runs after the last test method only','Runs after EACH @Test method in a test class','Runs after the entire suite','Runs after each test class'],answer:1,explanation:'@AfterMethod runs after each @Test method. Used for cleanup: closing connections, resetting state, releasing resources after each individual test.'},
{id:1875,topic:'testng',difficulty:'beginner',question:'What does `@BeforeClass` do in TestNG?',options:['Runs before each test method','Runs once before the first test method in the class is invoked','Runs before all classes in the suite','Runs before the test configuration'],answer:1,explanation:'@BeforeClass runs ONCE before the first test method in the current class. Used for expensive setup shared across all tests: initializing database connections, launching browsers, etc.'},
{id:1876,topic:'testng',difficulty:'beginner',question:'What does `@AfterClass` do in TestNG?',options:['Runs after each test method','Runs once after all test methods in the class have been invoked','Runs after the entire suite','Runs between test classes'],answer:1,explanation:'@AfterClass runs ONCE after all test methods in the current class. Used for class-level cleanup: closing shared connections, shutting down services, etc.'},
{id:1877,topic:'testng',difficulty:'beginner',question:'What does `@BeforeSuite` do in TestNG?',options:['Runs before each test','Runs once before all tests in the entire test suite','Runs before each class','Runs before a test group'],answer:1,explanation:'@BeforeSuite runs once before the entire suite starts. Used for global setup: starting test servers, initializing shared test data, configuring test environment.'},
{id:1878,topic:'testng',difficulty:'beginner',question:'What does `@AfterSuite` do in TestNG?',options:['Runs after each test','Runs once after all tests in the entire test suite have run','Runs after each class','Runs after a test group'],answer:1,explanation:'@AfterSuite runs once after the entire suite completes. Used for global teardown: stopping test servers, generating reports, cleaning up global test data.'},
{id:1879,topic:'testng',difficulty:'beginner',question:'What is TestNG\'s testng.xml file used for?',options:['A test report file','The XML configuration file that defines test suites, test classes, groups, parameters, listeners, and parallel execution settings','A dependency file','A properties file'],answer:1,explanation:'testng.xml (or suite.xml) defines: suite name, test groups to include/exclude, test classes, parameters, listeners, thread count for parallel execution, and more.'},
{id:1880,topic:'testng',difficulty:'intermediate',question:'How do you group tests in TestNG?',options:['Using @Group annotation','Using groups attribute in @Test: @Test(groups={"smoke","regression"}) and including/excluding in testng.xml','Using test class names','Using a groups.xml file'],answer:1,explanation:'@Test(groups={"smoke"}) assigns a test to the "smoke" group. testng.xml: <groups><run><include name="smoke"/></run></groups>. Run specific groups: mvn test -Dgroups=smoke.'},
{id:1881,topic:'testng',difficulty:'intermediate',question:'What is `@DataProvider` in TestNG?',options:['A data source annotation','An annotation on a method that returns Object[][] (or Iterator<Object[]>) to supply multiple sets of test data to @Test methods','A factory annotation','A parameter annotation'],answer:1,explanation:'@DataProvider(name="data") public Object[][] data() { return new Object[][]{{1,"a"},{2,"b"}}; } Then @Test(dataProvider="data") public void test(int n, String s) runs twice.'},
{id:1882,topic:'testng',difficulty:'intermediate',question:'What is `@Parameters` in TestNG?',options:['Same as @DataProvider','Injects values from testng.xml <parameter> tags into test methods at runtime','Marks optional parameters','Creates test parameters'],answer:1,explanation:'@Parameters({"browser","url"}) public void setup(String browser, String url) receives values from testng.xml: <parameter name="browser" value="chrome"/>. Good for environment config.'},
{id:1883,topic:'testng',difficulty:'intermediate',question:'What is test dependency in TestNG?',options:['Maven dependencies for tests','Using dependsOnMethods or dependsOnGroups to specify that a test runs only if its dependencies passed','A test ordering feature','Import dependencies'],answer:1,explanation:'@Test(dependsOnMethods={"login"}) makes the test skip if "login" failed. dependsOnGroups={"setup"} depends on all tests in the group. Use to model test workflows.'},
{id:1884,topic:'testng',difficulty:'intermediate',question:'What happens to a test that depends on a failed test in TestNG?',options:['It runs and may fail','It is marked as SKIP automatically unless alwaysRun=true is set','It throws an exception','It runs anyway'],answer:1,explanation:'By default, dependent tests are SKIPPED when their dependency fails or is skipped. @Test(dependsOnMethods={"login"}, alwaysRun=true) forces the test to run regardless.'},
{id:1885,topic:'testng',difficulty:'intermediate',question:'How do you enable parallel test execution in TestNG?',options:['Using a parallel flag in the test method','Setting parallel attribute in testng.xml: parallel="methods|classes|tests|instances" with thread-count','Using @Parallel annotation','Using multithreaded=true in @Test'],answer:1,explanation:'testng.xml: <suite parallel="methods" thread-count="5">. Options: methods (each method runs in separate thread), classes (each class in a thread), tests (each <test> tag), instances.'},
{id:1886,topic:'testng',difficulty:'intermediate',question:'What is `@Factory` annotation in TestNG?',options:['A Spring factory','An annotation on a method returning Object[] of test class instances — creates multiple instances with different parameters for the same test class','A class instantiator','A Selenium factory'],answer:1,explanation:'@Factory public Object[] createInstances() { return new Object[]{new MyTest("Chrome"),new MyTest("Firefox")}; } TestNG runs the full test class once per instance.'},
{id:1887,topic:'testng',difficulty:'intermediate',question:'What is `@Listeners` in TestNG?',options:['A test runner annotation','Attaches one or more listener classes to a test class: @Listeners({TestListener.class}). Listeners implement ITestListener, ISuiteListener, etc.','An event handler','A reporter annotation'],answer:1,explanation:'@Listeners({MyListener.class}) on the test class. MyListener implements ITestListener with onTestSuccess, onTestFailure, onTestSkipped, etc. Or register in testng.xml: <listeners>.'},
{id:1888,topic:'testng',difficulty:'intermediate',question:'What does `ITestListener` provide?',options:['Test configuration','Callbacks for test lifecycle events: onTestStart, onTestSuccess, onTestFailure, onTestSkipped, onTestFailedButWithinSuccessPercentage','A test filter','A test reporter'],answer:1,explanation:'ITestListener has 7 methods including onStart(ITestContext), onFinish(ITestContext), onTestSuccess, onTestFailure, onTestSkipped. Implement for custom reporting, screenshots, and logging.'},
{id:1889,topic:'testng',difficulty:'intermediate',question:'What is the `ISuiteListener` interface?',options:['A test method listener','A listener for suite-level events: onStart(ISuite) and onFinish(ISuite) — called when the suite starts and finishes','A class listener','A group listener'],answer:1,explanation:'ISuiteListener.onStart() fires before any test runs. ISuiteListener.onFinish() fires after all tests complete. Used for suite-level reporting, setup checks, and cleanup.'},
{id:1890,topic:'testng',difficulty:'intermediate',question:'What is `IReporter` in TestNG?',options:['A built-in test reporter','An interface implemented by custom reporter classes: generateReport(List<XmlSuite>, List<ISuite>, String outputDir) called after all tests complete','A log generator','A TestNG extension point'],answer:1,explanation:'IReporter.generateReport() is called after all tests with access to all results. Used for custom HTML/PDF/JSON reports. Register in testng.xml or via @Listeners.'},
{id:1891,topic:'testng',difficulty:'intermediate',question:'How do you set a test timeout in TestNG?',options:['Using Thread.sleep()','@Test(timeOut=5000) sets a timeout in milliseconds; if the test runs longer, it fails with a TimeoutException','Using a global timeout property','TestNG does not support timeouts'],answer:1,explanation:'@Test(timeOut=5000) fails the test if it runs for more than 5000ms. Can also set globally in testng.xml: <suite time-out="10000">. The test thread is interrupted after timeout.'},
{id:1892,topic:'testng',difficulty:'intermediate',question:'What does `@Test(invocationCount=5)` do?',options:['Runs 5 tests in the class','Runs the SAME test method 5 times consecutively (or in parallel with threadPoolSize)','Marks test for 5 executions of the suite','Runs with 5 different data sets'],answer:1,explanation:'invocationCount=5 repeats the test 5 times. Combined with threadPoolSize=3: runs 5 invocations using 3 threads. Useful for concurrency testing and flaky test detection.'},
{id:1893,topic:'testng',difficulty:'intermediate',question:'What is `@Test(successPercentage=80)` in TestNG?',options:['Passes if 80 assertions succeed','Passes the test if at least 80% of invocations (with invocationCount) succeed — remaining can fail without marking the test as failed','Passes with 80% coverage','Sets a minimum pass rate'],answer:1,explanation:'With invocationCount=10 and successPercentage=80: the test passes if at least 8 of 10 invocations succeed. Useful for flaky tests during debugging.'},
{id:1894,topic:'testng',difficulty:'intermediate',question:'What is a soft assertion in TestNG?',options:['An assertion that only warns','Using SoftAssert class: records failures without immediately failing the test; assertAll() at the end throws a combined failure if any assertions failed','An assertion for non-critical checks','A conditional assertion'],answer:1,explanation:'SoftAssert sa = new SoftAssert(); sa.assertEquals(a,b); sa.assertTrue(cond); sa.assertAll(); All assertions are checked and all failures reported together. Without assertAll(), failures are silently ignored.'},
{id:1895,topic:'testng',difficulty:'intermediate',question:'What is `Assert.assertEquals(actual, expected)` vs `Assert.assertEquals(expected, actual)` in TestNG?',options:['They are identical','TestNG convention: assertEquals(actual, expected). JUnit is opposite (expected, actual). Getting it right matters for clear error messages showing expected vs actual correctly.','Order does not matter','actual is always first in all frameworks'],answer:0,explanation:'TestNG Assert.assertEquals(actual, expected) — actual first, expected second. This affects error messages: "expected [expectedValue] but was [actualValue]". Wrong order gives confusing messages.'},
{id:1896,topic:'testng',difficulty:'intermediate',question:'What annotations does TestNG\'s @BeforeTest and @AfterTest apply to?',options:['Individual test methods','Runs once before/after all @Test methods in all classes defined within the <test> tag in testng.xml','All test classes in the suite','Test groups'],answer:1,explanation:'@BeforeTest runs before the first test method in any class in the <test> tag. @AfterTest runs after all test methods in the <test> tag. Scope: between @BeforeSuite and @BeforeClass.'},
{id:1897,topic:'testng',difficulty:'intermediate',question:'What is the execution order of TestNG annotations?',options:['@BeforeMethod → @BeforeClass → @BeforeSuite','@BeforeSuite → @BeforeTest → @BeforeClass → @BeforeMethod → @Test → @AfterMethod → @AfterClass → @AfterTest → @AfterSuite','All run simultaneously','Alphabetical order'],answer:1,explanation:'Correct order: BeforeSuite → BeforeTest → BeforeClass → BeforeMethod → Test → AfterMethod → AfterClass → AfterTest → AfterSuite. Mirrors setup and teardown hierarchy.'},
{id:1898,topic:'testng',difficulty:'intermediate',question:'How do you skip a test in TestNG?',options:['@Test(skip=true)','Throw SkipException in the test body, or use @Test(enabled=false) to permanently disable','Use @Ignore','Call Assert.skip()'],answer:1,explanation:'Programmatic skip: throw new SkipException("Skipping test"); Permanent disable: @Test(enabled=false). Conditional skip based on environment or feature flags.'},
{id:1899,topic:'testng',difficulty:'intermediate',question:'What does `@Test(enabled=false)` do in TestNG?',options:['Marks test as expected to fail','Excludes the test from execution — it will not be run, not counted as skipped or failed','Disables the test class','Marks as a placeholder'],answer:1,explanation:'@Test(enabled=false) prevents the method from being run. It will not appear in test results. Different from skip: a skipped test appears in results as SKIP.'},
{id:1900,topic:'testng',difficulty:'intermediate',question:'What is `@Test(expectedExceptions=IOException.class)` in TestNG?',options:['Catches IOException for the test','Marks the test as PASS only if the specified exception is thrown; fails if no exception or a different exception occurs','Suppresses the exception','Logs the exception'],answer:1,explanation:'@Test(expectedExceptions={IOException.class}) passes if and only if an IOException is thrown. Optional: expectedExceptionsMessageRegExp for validating the exception message.'},
{id:1901,topic:'testng',difficulty:'intermediate',question:'What is the `@Test(priority=)` attribute?',options:['Sets test importance','Controls execution order: lower priority numbers run first. Default priority is 0. Tests with same priority run in alphabetical order by method name.','Sets the thread priority','A deprecated feature'],answer:1,explanation:'@Test(priority=1) runs after @Test(priority=0). Negative priorities allowed. Use sparingly — prefer dependsOnMethods/Groups for logical ordering, priority for unrelated ordering.'},
{id:1902,topic:'testng',difficulty:'intermediate',question:'What is a TestNG reporter output?',options:['Console output only','The Reporter class provides Reporter.log("message") to add messages to the TestNG HTML report, separate from console logging','An email reporter','A Slack reporter'],answer:1,explanation:'Reporter.log("Step 1 completed") adds messages to the HTML report\'s test output tab. Reporter.log(message, true) also logs to stdout. Visible in generated index.html and testng-results.xml.'},
{id:1903,topic:'testng',difficulty:'intermediate',question:'What is TestNG\'s default output directory?',options:['"reports" folder','"test-output" folder in the project root','Target/surefire-reports','Console only'],answer:1,explanation:'TestNG generates reports in the "test-output" directory by default. Contains: index.html (overview), emailable-report.html, testng-results.xml, and per-class XML files.'},
{id:1904,topic:'testng',difficulty:'intermediate',question:'How does TestNG integrate with Maven?',options:['Does not integrate','Via the maven-surefire-plugin: configure suiteXmlFiles to point to testng.xml; surefire runs TestNG by detecting it on the classpath','Via the TestNG Maven plugin only','Via testng-maven.xml'],answer:1,explanation:'pom.xml: <plugin>maven-surefire-plugin<suiteXmlFiles><suiteXmlFile>testng.xml</suiteXmlFile></suiteXmlFiles>. With TestNG on classpath, surefire auto-detects it. Run: mvn test.'},
{id:1905,topic:'testng',difficulty:'intermediate',question:'What is `@DataProvider(parallel=true)` in TestNG?',options:['Runs data providers in parallel','Runs the test method once for each dataset from the DataProvider in parallel threads, controlled by thread-count in testng.xml','Creates a parallel data source','Makes the test class parallel'],answer:1,explanation:'@DataProvider(name="data", parallel=true) runs each data row as a separate parallel invocation. The thread count is set by data-provider-thread-count in testng.xml or suite configuration.'},
{id:1906,topic:'testng',difficulty:'intermediate',question:'What is IRetryAnalyzer in TestNG?',options:['A test re-runner for passed tests','An interface for retrying failed tests: implement retry(ITestResult result) returning true to retry, false to not retry','An assertion retry mechanism','A flaky test detector'],answer:1,explanation:'class MyRetry implements IRetryAnalyzer { int count=0; int max=2; public boolean retry(ITestResult r){ return count++<max; } }. @Test(retryAnalyzer=MyRetry.class) retries up to 2 times.'},
{id:1907,topic:'testng',difficulty:'intermediate',question:'What does `ITestResult` provide?',options:['Test result enum only','Represents a test result with: getStatus() (SUCCESS/FAILURE/SKIP), getThrowable(), getMethod(), getParameters(), getStartMillis(), getEndMillis()','A test reporter','A test configuration'],answer:1,explanation:'ITestResult.SUCCESS=1, FAILURE=2, SKIP=3. getThrowable() returns the exception for failures. getMethod().getMethodName() gets the test name. Used in listeners and retry analyzers.'},
{id:1908,topic:'testng',difficulty:'intermediate',question:'What is a TestNG suite defined in testng.xml?',options:['A collection of tests from one class','A collection of <test> elements defining groups of test classes to run together with shared configuration','A test file','A package definition'],answer:1,explanation:'<suite name="Suite"><test name="Smoke"><classes><class name="com.test.LoginTest"/></classes></test></suite>. A suite can contain multiple <test> elements with different configurations.'},
{id:1909,topic:'testng',difficulty:'intermediate',question:'How do you include/exclude methods in testng.xml?',options:['Using @Include/@Exclude','Using <methods><include name="testLogin"/><exclude name="testLogout"/></methods> within a <class> element','Using command line flags','Using a properties file'],answer:1,explanation:'<class name="LoginTest"><methods><include name="testLogin"/></methods></class> runs only testLogin. <exclude name="flaky"/> skips that method. Wildcard: <include name="test.*"/> supports regex.'},
{id:1910,topic:'testng',difficulty:'intermediate',question:'What is the difference between TestNG and JUnit 5?',options:['They are identical','TestNG has native XML-based suite config, built-in grouping, dependsOnMethods, DataProvider, and factory. JUnit 5 uses @ExtendWith, @ParameterizedTest, has better lambda support and is more modular.','JUnit is older only','TestNG is Java-only'],answer:1,explanation:'Both are mature. TestNG advantages: built-in parallel, groups, dependency, DataProvider. JUnit 5 advantages: extension model, @Nested classes, better IDE integration, large Spring Boot ecosystem support.'},
{id:1911,topic:'testng',difficulty:'intermediate',question:'What is `@BeforeGroups` in TestNG?',options:['Runs before any test group','Runs before the first test method belonging to any of the listed groups: @BeforeGroups({"smoke"})','Runs before all groups','A setup method for groups'],answer:1,explanation:'@BeforeGroups(groups={"smoke"}) runs once before the first test in the "smoke" group executes. Similarly @AfterGroups runs after the last test in the group.'},
{id:1912,topic:'testng',difficulty:'intermediate',question:'How do you run multiple test suites in TestNG?',options:['Using multiple testng.xml files run separately','Using a parent testng.xml with <suite-files>: <suite-file path="suite1.xml"/> referencing other suite files, or via Maven surefire configuration','Using multi-suite.xml','Using TestRunner API'],answer:1,explanation:'Nested suites: <suite name="all"><suite-files><suite-file path="smoke.xml"/><suite-file path="regression.xml"/></suite-files></suite>. Or configure surefire to include multiple XML files.'},
{id:1913,topic:'testng',difficulty:'intermediate',question:'What does `Assert.fail(String message)` do in TestNG?',options:['Marks a warning','Unconditionally fails the current test with the given message — useful for not-yet-implemented tests or reaching unreachable code paths','Logs a failure','Skips the test'],answer:1,explanation:'Assert.fail("Not implemented") immediately fails the test. Useful in catch blocks: if you expect no exception but want to fail if one occurs: catch(Exception e){ Assert.fail("Unexpected exception: "+e); }'},
{id:1914,topic:'testng',difficulty:'intermediate',question:'What is `@Test(alwaysRun=true)` used for?',options:['Forces the test to run first','Runs the test even if it depends on a failed or skipped test','Prevents the test from being grouped','Runs the test in all configurations'],answer:1,explanation:'@Test(alwaysRun=true) on a test that uses dependsOnMethods/dependsOnGroups means it will run even if the depended-upon test failed or was skipped. The test is always executed.'},
{id:1915,topic:'testng',difficulty:'intermediate',question:'What is the `@Ignore` equivalent in TestNG?',options:['@Ignore from JUnit can also be used','@Test(enabled=false) is the TestNG equivalent of JUnit @Ignore','@Skip','@Disabled'],answer:1,explanation:'TestNG uses @Test(enabled=false) to disable a test. JUnit 5 uses @Disabled. Note: @Ignore is JUnit 4-specific and does not work the same way in pure TestNG projects.'},
{id:1916,topic:'testng',difficulty:'intermediate',question:'What is the `ISuiteListener` vs `ITestListener` scope difference?',options:['No difference','ISuiteListener fires at suite start/finish; ITestListener fires for each individual test method (onTestStart, onTestSuccess, etc.)','ISuiteListener is deprecated','ITestListener is for classes'],answer:1,explanation:'ISuiteListener: 2 methods (onStart/onFinish per suite). ITestListener: 7+ methods per test method. ITestListener also has onStart(ITestContext) and onFinish(ITestContext) for the test tag scope.'},
{id:1917,topic:'testng',difficulty:'advanced',question:'What is TestNG\'s `IMethodInterceptor`?',options:['A method filter','An interface allowing you to alter the list of test methods that TestNG will run: implement intercept(List<IMethodInstance>, ITestContext) to reorder or filter methods at runtime','A proxy generator','A test decorator'],answer:1,explanation:'IMethodInterceptor.intercept() receives the full list of test methods and can return a modified list (reordered, filtered, or augmented). Registered as a listener.'},
{id:1918,topic:'testng',difficulty:'advanced',question:'What is `IAnnotationTransformer` in TestNG?',options:['Transforms annotations at compile time','Allows modifying @Test and other annotations at runtime before test execution: change enabled, groups, priority, dataProvider, etc.','A reflection utility','An annotation processor'],answer:1,explanation:'IAnnotationTransformer.transform(ITestAnnotation, Class, Constructor, Method) is called for each test method. Use to dynamically set dataProvider, enabled, groups based on runtime conditions.'},
{id:1919,topic:'testng',difficulty:'advanced',question:'What is `IHookable` in TestNG?',options:['A WebHook interface','Allows intercepting @Test method invocations: run(IHookCallBack callBack, ITestResult result) is called instead of the test method, allowing pre/post processing','A cleanup hook','A test filter hook'],answer:1,explanation:'IHookable: run(callback, result) — you must call callback.runTestMethod(result) to actually execute the test. Used for AOP-style wrapping (screenshot on failure, timing, etc.).'},
{id:1920,topic:'testng',difficulty:'advanced',question:'What is `IConfigurable` in TestNG?',options:['A configuration reader','Like IHookable but for @Before/@After configuration methods: run(IConfigureCallBack, ITestResult) intercepts setup/teardown execution','A config file parser','A TestNG plugin interface'],answer:1,explanation:'IConfigurable wraps @BeforeMethod, @AfterMethod etc. in the same way IHookable wraps @Test. Useful for AOP-style wrapping of test lifecycle methods.'},
{id:1921,topic:'testng',difficulty:'intermediate',question:'What is TestNG\'s XML-based suite parallel="tests" mode?',options:['Each test method in parallel','Each <test> tag in testng.xml runs in a separate thread. Test classes within a <test> tag run sequentially.','Each class in parallel','Each method and class in parallel'],answer:1,explanation:'parallel="tests": each <test> element runs in its own thread. Useful for running different configurations (browser, environment) concurrently while keeping classes within each test sequential.'},
{id:1922,topic:'testng',difficulty:'intermediate',question:'What is TestNG\'s XML-based suite parallel="classes" mode?',options:['Each method in parallel','Each class runs in a separate thread; methods within a class run sequentially in the same thread','Each test runs together','Random parallel execution'],answer:1,explanation:'parallel="classes": each test class gets its own thread. Methods within the class run sequentially. Good for independent test classes that share no state.'},
{id:1923,topic:'testng',difficulty:'intermediate',question:'What are TestNG\'s assertion methods?',options:['Only assertEquals and assertTrue','Assert.assertEquals, assertTrue, assertFalse, assertNull, assertNotNull, assertSame, assertNotSame, assertThrows, fail — from org.testng.Assert','assertEquals and assertThat only','Assertions from JUnit only'],answer:1,explanation:'TestNG provides: assertEquals(actual,expected), assertTrue(condition), assertFalse(), assertNull(), assertNotNull(), assertSame(a==b reference), assertNotSame(), fail(). SoftAssert for non-fatal assertions.'},
{id:1924,topic:'testng',difficulty:'intermediate',question:'What does `Assert.assertSame(actual, expected)` check?',options:['Value equality','Reference equality: passes only if actual and expected refer to the SAME object in memory (==), not just equal values','String equality','List order equality'],answer:1,explanation:'assertSame checks reference equality (same object). assertNotSame checks they are different objects. Compare with assertEquals which checks .equals() (value equality).'},
{id:1925,topic:'testng',difficulty:'intermediate',question:'What is the difference between TestNG `@Test` and JUnit 5 `@Test`?',options:['They are identical','TestNG @Test has attributes like groups, dependsOnMethods, dataProvider, invocationCount, timeOut, expectedExceptions. JUnit 5 @Test is simpler but uses @ParameterizedTest, @ExtendWith for extensions.','JUnit @Test is more powerful','TestNG @Test is deprecated'],answer:1,explanation:'TestNG @Test is richer: @Test(groups, dependsOnMethods, dataProvider, invocationCount, timeOut, priority, enabled, expectedExceptions). JUnit 5 separates concerns into dedicated annotations.'},
{id:1926,topic:'testng',difficulty:'advanced',question:'What is a TestNG `@Test` method\'s required return type?',options:['Must return boolean','Must return void','Can return any type','Must return ITestResult'],answer:1,explanation:'TestNG @Test methods must return void. Any return value is ignored. Methods with other return types will not be recognized as test methods by some test runners, though TestNG itself may still run them.'},
{id:1927,topic:'testng',difficulty:'intermediate',question:'What is `@DataProvider` with `Iterator<Object[]>` return type?',options:['Does not work','Returns test data lazily via an iterator — suitable for very large data sets that should not be loaded into memory all at once','A parallel data provider','A streaming data provider'],answer:1,explanation:'DataProvider can return Iterator<Object[]> instead of Object[][] for lazy data generation — useful for database-driven or file-driven large test data sets without memory overhead.'},
{id:1928,topic:'testng',difficulty:'intermediate',question:'How do you share a DataProvider across multiple test classes in TestNG?',options:['Define it in a base class','Put @DataProvider in a separate utility class; reference with dataProviderClass attribute: @Test(dataProvider="data", dataProviderClass=DataUtils.class)','Use a static @DataProvider','Copy-paste across classes'],answer:1,explanation:'@Test(dataProvider="userData", dataProviderClass=TestData.class). The DataProvider class must be accessible. The method can be static. This promotes reuse without inheritance.'},
{id:1929,topic:'testng',difficulty:'intermediate',question:'What is the `testng-results.xml` file?',options:['A test configuration file','An XML report generated by TestNG containing all test results including status, parameters, time, and exception details for each test method','A Maven report','A JUnit XML report'],answer:1,explanation:'testng-results.xml in test-output/ contains structured results. Compatible with CI tools (Jenkins, Azure DevOps). The surefire plugin also generates junit-compatible XML for CI integration.'},
{id:1930,topic:'testng',difficulty:'intermediate',question:'What is TestNG\'s `emailable-report.html`?',options:['A report that auto-emails','A self-contained HTML report generated by TestNG suitable for emailing to stakeholders, showing pass/fail/skip counts and test details','An HTML dashboard','A test summary page'],answer:1,explanation:'emailable-report.html in test-output/ is a clean HTML file with test results. Can be attached to CI/CD emails. The "index.html" is a more detailed framed report with navigation.'},
{id:1931,topic:'testng',difficulty:'advanced',question:'What is `TestNG.xml` vs programmatic TestNG execution?',options:['They are identical','XML: declarative suite definition run via Maven or command line. Programmatic: using TestNG API (TestNG tng = new TestNG(); tng.setTestClasses(...); tng.run()) for dynamic test running','XML is deprecated','Programmatic is slower'],answer:1,explanation:'TestNG tng = new TestNG(); XmlSuite suite = new XmlSuite(); XmlTest test = new XmlTest(suite); test.setXmlClasses(classes); tng.setXmlSuites(suites); tng.run(). Enables dynamic test generation.'},
{id:1932,topic:'testng',difficulty:'intermediate',question:'What is `@BeforeMethod` vs `@BeforeClass` timing difference?',options:['No timing difference','@BeforeMethod: runs before EACH test method (n tests = n runs). @BeforeClass: runs ONCE before all methods in the class. Use BeforeClass for expensive shared setup.','@BeforeClass runs after','@BeforeMethod runs once'],answer:1,explanation:'10 test methods: @BeforeMethod runs 10 times; @BeforeClass runs once. Use @BeforeClass for driver initialization; @BeforeMethod for per-test state reset.'},
{id:1933,topic:'testng',difficulty:'intermediate',question:'What are TestNG\'s `@Test` singleThreaded attribute?',options:['Forces single CPU','@Test(singleThreaded=true) on a class ensures all methods in that class run in the same thread even when the suite is configured for parallel execution','Makes the test non-concurrent','Forces sequential execution of the entire suite'],answer:1,explanation:'singleThreaded=true (class-level in testng.xml or @Test) prevents methods from that class from being distributed across threads in parallel mode. Used for stateful tests.'},
{id:1934,topic:'testng',difficulty:'intermediate',question:'What is `preserve-order` in testng.xml?',options:['Sorts tests alphabetically','preserve-order="true" on the <test> element runs test classes and methods in the order they appear in testng.xml (default is preserve order)','Prevents test reordering','A deprecated attribute'],answer:1,explanation:'<test preserve-order="true"> maintains the order of class/method definitions in testng.xml. preserve-order="false" lets TestNG reorder methods. Default is true.'},
{id:1935,topic:'testng',difficulty:'advanced',question:'What is the `verbose` attribute in testng.xml?',options:['Enables debug mode','Controls console output verbosity: verbose="2" is default; higher values (up to 10) output more information about test execution','Enables logging','A deprecated attribute'],answer:1,explanation:'<suite verbose="2"> controls the amount of TestNG output to console. verbose=0 is minimal, verbose=10 is maximum detail. Useful for debugging suite configuration issues.'},
{id:1936,topic:'testng',difficulty:'intermediate',question:'What is `IExecutionListener` in TestNG?',options:['A test execution proxy','Provides onExecutionStart() and onExecutionFinish() — called once when TestNG starts and finishes, before BeforeSuite and after AfterSuite','An async execution listener','A thread execution monitor'],answer:1,explanation:'IExecutionListener fires before any suite starts and after all suites finish — the broadest scope. Useful for initializing/cleaning up global test infrastructure like logging frameworks.'},
{id:1937,topic:'testng',difficulty:'advanced',question:'What is the difference between TestNG `SKIP` and `FAILURE` statuses?',options:['No difference','SKIP: test was intentionally or conditionally not run (SkipException or dependency failed). FAILURE: test ran but an assertion or exception caused it to fail.','SKIP means dependency failed only','FAILURE is fatal'],answer:1,explanation:'SKIP appears when: SkipException thrown, enabled=false, dependency failed/skipped. FAILURE: assertion failed, unexpected exception, or timeout. Both appear in reports with different colors.'},
{id:1938,topic:'testng',difficulty:'intermediate',question:'What is TestNG\'s `@Test(description=)` attribute?',options:['An annotation comment','Provides a human-readable description of the test visible in reports, helping document test purpose without reading code','A test tag','A test ID'],answer:1,explanation:'@Test(description="Verify login with valid credentials") improves report readability. The description appears in TestNG HTML reports. Best practice for documenting test intent.'},
{id:1939,topic:'testng',difficulty:'intermediate',question:'How do you parameterize TestNG tests from an Excel or database source?',options:['TestNG has built-in Excel support','Implement @DataProvider that reads from Excel (using Apache POI) or database (using JDBC) and returns Object[][]','Use @Parameters with Excel','Use a CSV annotation'],answer:1,explanation:'@DataProvider(name="excelData") public Object[][] getData() { // use Apache POI to read .xlsx; return data[][]; }. @Test(dataProvider="excelData") receives the data rows.'},
{id:1940,topic:'testng',difficulty:'advanced',question:'What is TestNG\'s dependency injection for test methods?',options:['Spring injection only','TestNG injects special parameter types: ITestContext, ITestResult, XmlTest into @Test and configuration methods when declared as parameters','Constructor injection','Annotation-based injection'],answer:1,explanation:'@BeforeMethod public void setup(ITestContext context) receives the TestNG context. @Test can receive ITestResult. TestNG auto-injects these special types without additional configuration.'},
{id:1941,topic:'testng',difficulty:'intermediate',question:'What is `ITestContext` in TestNG?',options:['A test configuration class','Provides runtime test context information: getPassedTests(), getFailedTests(), getSkippedTests(), getSuite(), getCurrentXmlTest(), getOutputDirectory()','A test result container','A context for before/after methods only'],answer:1,explanation:'ITestContext is available in @BeforeTest, @AfterTest, and via ITestListener. Use to access all results so far, suite name, test name, and output directory at runtime.'},
{id:1942,topic:'testng',difficulty:'intermediate',question:'What is TestNG\'s `thread-count` attribute in testng.xml?',options:['Maximum CPU threads','Sets the number of threads for parallel test execution in the thread pool','The number of retries','A timeout in threads'],answer:1,explanation:'<suite parallel="methods" thread-count="5"> uses up to 5 threads to run test methods concurrently. thread-count must be set when parallel is not "none".'},
{id:1943,topic:'testng',difficulty:'intermediate',question:'What is `@Test(singleThreaded=true)` vs `synchronized` in TestNG?',options:['They are identical','singleThreaded=true in TestNG forces all methods in the class to run in the same thread; synchronized is a Java keyword for thread-safe method access — different concepts','singleThreaded is for classes only','synchronized is not related'],answer:1,explanation:'singleThreaded=true: TestNG scheduler runs all class methods in one thread. synchronized: Java-level mutual exclusion preventing concurrent execution from multiple threads. Use singleThreaded for stateful browser tests.'},
{id:1944,topic:'testng',difficulty:'advanced',question:'What is TestNG\'s `@Test` with `groups` and how to exclude a group?',options:['Use @Test(excludeGroups)','In testng.xml: <groups><run><exclude name="wip"/></run></groups> or @Test(groups="regression") combined with suite-level <exclude name="regression"/>','Use enabled=false on the group','Use @ExcludeGroup'],answer:1,explanation:'Group exclusion is in testng.xml: <groups><run><include name="smoke"/><exclude name="wip"/></run></groups>. Cannot include and exclude the same group. Inclusion takes priority over class-level definition.'},
{id:1945,topic:'testng',difficulty:'intermediate',question:'What is `@Test(retryAnalyzer=)` best practice?',options:['Use on all tests by default','Apply selectively on known flaky tests only; combining with a maximum retry count; log all retries; not a substitute for fixing flaky tests','Use for all failing tests','Apply at class level always'],answer:1,explanation:'Best practice: use retryAnalyzer sparingly on genuinely flaky tests (network tests, timing-sensitive). Always log retries. Set max retries to 2-3. Investigate root cause of flakiness.'},
{id:1946,topic:'testng',difficulty:'intermediate',question:'What is the purpose of `@Test(groups={"regression","smoke"})` specifying multiple groups?',options:['Forces both groups to run','Assigns the test to multiple groups, so it will run when either group is selected in testng.xml or command line','A union of groups','Requires both groups to be included'],answer:1,explanation:'A test can belong to multiple groups. If testng.xml includes "smoke" OR "regression" groups, the test runs in either case. The test is included as long as at least one of its groups is included.'},
{id:1947,topic:'testng',difficulty:'intermediate',question:'What is TestNG\'s `@AfterMethod(alwaysRun=true)` use case?',options:['Forces AfterMethod to run first','Ensures cleanup runs even if @BeforeMethod or the test method throws an exception — essential for resource cleanup','Runs after all test methods','A required attribute'],answer:1,explanation:'@AfterMethod(alwaysRun=true) guarantees the teardown runs regardless of test outcome, including when the test threw an exception. Critical for WebDriver.quit(), connection.close(), etc.'},
{id:1948,topic:'testng',difficulty:'intermediate',question:'What is TestNG\'s XML element `<package>` used for?',options:['A Maven package definition','Includes all test classes from a Java package: <packages><package name="com.tests.smoke"/></packages> auto-discovers all TestNG test classes in that package','A namespace declaration','A class loader configuration'],answer:1,explanation:'<packages><package name="com.example.tests"/></packages> auto-includes all classes with @Test in the package. Simpler than listing each class. Uses reflection to discover test classes.'},
{id:1949,topic:'testng',difficulty:'advanced',question:'What is `ExtentReports` and how does it integrate with TestNG?',options:['A built-in TestNG reporter','A popular third-party HTML reporting library; integrates via ITestListener to capture test results and generate rich, styled HTML reports with screenshots','A Maven plugin','A TestNG extension'],answer:1,explanation:'ExtentReports: implement ITestListener; in onTestSuccess/Failure/Skip use extent.createTest(name).pass/fail/skip(). @Listeners(ExtentReportListener.class) on base test class. Generates interactive HTML reports.'},
{id:1950,topic:'testng',difficulty:'advanced',question:'What is Allure reporting with TestNG?',options:['A built-in TestNG report','An advanced reporting framework providing rich HTML reports with timeline, categories, behaviors; integrates via AllureTestNG listener and @Step, @Attachment annotations','An email report','A database reporter'],answer:1,explanation:'Add allure-testng dependency; configure surefire with AspectJ agent; use @Step("description") on helper methods; allure serve target/allure-results generates the interactive report.'},
{id:1951,topic:'testng',difficulty:'intermediate',question:'What is `TestNG.xml` `allow-return-values="true"` attribute?',options:['Ignores return values','Allows test methods that return non-void values to be recognized and run as test methods — normally non-void methods are not run','Validates return values','A debugging attribute'],answer:1,explanation:'By default, TestNG ignores non-void methods. allow-return-values="true" in testng.xml: <suite allow-return-values="true"> enables running @Test methods with non-void return types.'},
{id:1952,topic:'testng',difficulty:'intermediate',question:'What is a TestNG listener registration order?',options:['Alphabetical','Listeners registered in testng.xml or @Listeners run in the order they are added; service loader listeners in undetermined order','Priority-based','Last-in first-out'],answer:1,explanation:'@Listeners({ListenerA.class, ListenerB.class}) — A runs before B for onTestStart, B runs before A for onTestFinish (reversed). Testng.xml <listeners> order also matters.'},
{id:1953,topic:'testng',difficulty:'advanced',question:'What is `ServiceLoader` integration for TestNG listeners?',options:['A Java service API','Adding META-INF/services/org.testng.ITestNGListener file with listener class names causes TestNG to auto-register them — no @Listeners or testng.xml needed','A Maven plugin','An SPI for plugins'],answer:1,explanation:'Create META-INF/services/org.testng.ITestNGListener with your listener class name. TestNG uses Java ServiceLoader to auto-discover and register it. Zero-config listener registration.'},
{id:1954,topic:'testng',difficulty:'intermediate',question:'What is the difference between TestNG `@BeforeMethod` and Selenium `@BeforeEach` (JUnit)?',options:['They are identical in behavior','@BeforeMethod (TestNG) and @BeforeEach (JUnit 5) both run before each test method and serve the same purpose; only the annotation name differs','@BeforeMethod runs once','@BeforeEach is inherited'],answer:1,explanation:'TestNG: @BeforeMethod runs before each @Test. JUnit 5: @BeforeEach runs before each @Test. Same semantic purpose. Migration between frameworks requires renaming annotations.'},
{id:1955,topic:'testng',difficulty:'intermediate',question:'What is `TestNG.setVerbose(int)` used for in programmatic runs?',options:['Sets test priority','Controls the amount of logging TestNG outputs to console in programmatic API usage: TestNG tng = new TestNG(); tng.setVerbose(2)','Sets retry count','Sets timeout'],answer:1,explanation:'tng.setVerbose(n) where n=0 (none) to 10 (max debug). Setting 0 in CI suppresses noise. Setting 10 for debugging framework issues. Same as verbose attribute in testng.xml.'},
{id:1956,topic:'testng',difficulty:'advanced',question:'What is `@Test(ignoreMissingDependencies=true)` in TestNG?',options:['Ignores failed dependencies','When a dependency method does not exist (was renamed or deleted), the test still runs instead of being skipped/failed with dependency error','Runs despite skip','Ignores all dependencies'],answer:1,explanation:'ignoreMissingDependencies=true: if the declared dependency method is not found in the test run (excluded or missing), the test still runs. Default false causes a skip/error.'},
{id:1957,topic:'testng',difficulty:'intermediate',question:'What is the `@BeforeClass` scope in TestNG?',options:['Runs once per test method','Runs once for the class\'s entire execution in the current test run. In parallel classes mode, it runs in the thread designated for that class.','Runs once per JVM','Runs in all threads'],answer:1,explanation:'@BeforeClass: once per class instance per test run. In parallel="classes" mode, each class gets its own thread and its @BeforeClass runs in that thread.'},
{id:1958,topic:'testng',difficulty:'intermediate',question:'What is `TestNG.setOutputDirectory(String)` used for?',options:['Changes the class output','Redirects TestNG report generation to a custom directory instead of default "test-output/"','Changes the Maven output','Sets the log directory'],answer:1,explanation:'tng.setOutputDirectory("custom-reports/") or testng.xml: <suite output-dir="custom-reports/"> changes where TestNG generates its reports.'},
{id:1959,topic:'testng',difficulty:'advanced',question:'What is `GroupByInstances` in TestNG?',options:['Groups by class name','When set to true, tests from the same instance are grouped together before running other instances, avoiding thread interleaving in @Factory scenarios','Groups by thread','A parallel mode'],answer:1,explanation:'<test group-by-instances="true"> ensures all methods from one @Factory instance run together before switching to the next instance, preventing state corruption in multi-instance scenarios.'},
{id:1960,topic:'testng',difficulty:'intermediate',question:'What is `TestNG.addListener(ITestNGListener)` used for?',options:['Adds to testng.xml','Programmatically adds a listener when running TestNG via API: tng.addListener(new MyListener()) without needing @Listeners or testng.xml configuration','A method interceptor','A plugin hook'],answer:1,explanation:'For programmatic TestNG runs: TestNG tng = new TestNG(); tng.addListener(new MyReporter()); tng.setTestClasses(classes); tng.run(). Useful in custom test runners and CI scripts.'},
{id:1961,topic:'testng',difficulty:'advanced',question:'What is `@Test` with `description` vs JavaDoc in TestNG?',options:['description is better','description appears in HTML reports; JavaDoc is for IDE/developer reading only. Both are useful: description for report clarity, JavaDoc for code documentation.','JavaDoc is visible in reports','They are identical'],answer:1,explanation:'@Test(description="Login with valid credentials") appears in TestNG HTML report columns. JavaDoc comments are for IDE hover and generated Javadoc pages. Use both for different audiences.'},
{id:1962,topic:'testng',difficulty:'intermediate',question:'What is `@Test(threadPoolSize=5, invocationCount=10)` combination?',options:['Runs 5 tests in 10 seconds','Runs the test 10 times total using 5 threads concurrently — for concurrency and stress testing','Creates 10 threads','Runs 5 times'],answer:1,explanation:'invocationCount=10: run 10 times. threadPoolSize=5: use 5 concurrent threads for those invocations. TestNG distributes the 10 invocations across 5 threads for parallelism.'},
{id:1963,topic:'testng',difficulty:'intermediate',question:'What is TestNG\'s `exclude-groups` in testng.xml?',options:['Same as group exclude','<exclude name="unstable"/> inside <groups><run> excludes all tests in the "unstable" group even if they are also in an included group','A test filter','An environment filter'],answer:1,explanation:'<groups><run><include name="regression"/><exclude name="unstable"/></run></groups> runs all regression tests EXCEPT those also tagged as "unstable". Exclusion takes precedence.'},
{id:1964,topic:'testng',difficulty:'advanced',question:'What is TestNG\'s `IObjectFactory` interface?',options:['A test class factory','Allows providing a custom object factory for creating test class instances: useful for DI frameworks (Guice, Spring) to inject dependencies into test classes','An annotation factory','A suite factory'],answer:1,explanation:'IObjectFactory.newInstance(Constructor, Object...) creates test class instances. Implement to use Spring context: return (T) applicationContext.getBean(clazz). Register in testng.xml: <object-factory>.'},
{id:1965,topic:'testng',difficulty:'advanced',question:'What is the `@Mock` annotation in TestNG-related testing?',options:['A TestNG annotation','Not a TestNG annotation — @Mock comes from Mockito library (@Mock in Mockito or @MockBean in Spring Test). TestNG tests commonly use Mockito alongside TestNG.','An assertion annotation','A data provider annotation'],answer:1,explanation:'@Mock is from org.mockito.Mock. @MockitoAnnotations.openMocks(this) initializes mocks in @BeforeMethod. Or use MockitoExtension with JUnit 5. TestNG does not have a built-in mock annotation.'},
{id:1966,topic:'testng',difficulty:'intermediate',question:'How do you use TestNG with Spring framework?',options:['TestNG does not support Spring','Use AbstractTestNGSpringContextTests or @DirtiesContext, loading Spring context via @ContextConfiguration or @SpringBootTest with TestNG listener SpringTestNGContextManager','Use Spring annotations only','Use TestNG\'s @Inject'],answer:1,explanation:'extend AbstractTestNGSpringContextTests (Spring TestContext Framework) or add SpringTestNGContextBootstrapper. @SpringBootTest works with TestNG too. Spring beans are autowired into test classes.'},
{id:1967,topic:'testng',difficulty:'intermediate',question:'What is TestNG\'s test output for CI/CD systems?',options:['Console only','testng-results.xml and surefire XML reports are consumed by CI systems (Jenkins TestNG plugin, Azure DevOps) to show test trends and results','An HTML report only','A JSON report'],answer:1,explanation:'Jenkins TestNG plugin reads testng-results.xml. Maven Surefire generates JUnit-compatible XML consumed by Jenkins JUnit plugin. Both support trend graphs and failure details.'},
{id:1968,topic:'testng',difficulty:'intermediate',question:'What is `@BeforeMethod` method signature in TestNG?',options:['Must be public void','Must be public, can optionally accept ITestResult parameter or methods parameter (Method[] for inspection); no return value','Can be any return type','Must be static'],answer:1,explanation:'@BeforeMethod public void setup(Method method) receives the current test Method object. @BeforeMethod public void setup(ITestResult result) also works. Both must be public void.'},
{id:1969,topic:'testng',difficulty:'advanced',question:'What is TestNG\'s `@Test` attribute `threadPoolSize` constraint?',options:['No constraints','threadPoolSize is only meaningful when invocationCount > 1; without invocationCount, it is ignored','Must equal thread-count in testng.xml','Must be power of 2'],answer:1,explanation:'threadPoolSize without invocationCount has no effect. Both are needed: @Test(threadPoolSize=3, invocationCount=9) creates 3 threads each running 3 invocations.'},
{id:1970,topic:'testng',difficulty:'advanced',question:'What is TestNG\'s XML `<define>` element under `<groups>`?',options:['A variable definition','Defines a meta-group that includes other groups: <define name="allSanity"><include name="smoke"/><include name="basic"/></define> — can then include "allSanity"','An alias for a group','A group hierarchy'],answer:1,explanation:'<groups><define name="allTests"><include name="smoke"/><include name="regression"/></define><run><include name="allTests"/></run></groups> defines composite group "allTests" containing both groups.'},
{id:1971,topic:'testng',difficulty:'intermediate',question:'What does TestNG\'s `index.html` report include?',options:['Only passing tests','Test summary (total/pass/fail/skip counts), timeline, per-class results, and navigation to detailed test output, generated in test-output/ directory','Configuration details','Java stack traces only'],answer:1,explanation:'index.html is TestNG\'s default framed HTML report: left frame for navigation (suite/test/class), right frame for details. Shows counts, duration, and links to test output. emailable-report.html is simpler.'},
{id:1972,topic:'testng',difficulty:'intermediate',question:'What is `@DataProvider(name=)` vs positional DataProvider in TestNG?',options:['No difference','name= links the DataProvider to @Test(dataProvider="name"). Without a name, it defaults to the method name. Using named DataProviders is more explicit and maintainable.','Positional is deprecated','Named is slower'],answer:1,explanation:'@DataProvider(name="loginData") is referenced by @Test(dataProvider="loginData"). Without name, method name is the provider name. Explicit naming is best practice for clarity.'},
{id:1973,topic:'testng',difficulty:'advanced',question:'What is TestNG\'s `concurrent.use.new.context="true"` in testng.xml?',options:['Creates new TestNG context','Forces creation of a new test context for each test thread in parallel mode, isolating ITestContext state per thread','An async flag','A memory optimization'],answer:1,explanation:'concurrent.use.new.context: in parallel execution, each thread gets its own ITestContext to prevent thread-unsafe shared state in the context. Useful for complex parallel reporting scenarios.'},
{id:1974,topic:'testng',difficulty:'intermediate',question:'What is the purpose of `@Test(invocationTimeOut=)` vs `timeOut=`?',options:['They are identical','timeOut: maximum time for a SINGLE invocation. invocationTimeOut: maximum TOTAL time for ALL invocations (when invocationCount > 1). Different scopes.','invocationTimeOut is deprecated','timeOut is global'],answer:1,explanation:'@Test(invocationCount=10, timeOut=1000, invocationTimeOut=8000): each of 10 runs gets max 1 second; all 10 together must complete within 8 seconds. Useful for concurrent stress tests.'},
{id:1975,topic:'testng',difficulty:'advanced',question:'What is a TestNG test class instance per test vs shared instance?',options:['Always one instance','By default, TestNG creates one instance of the test class per <test> tag. With @Factory or IObjectFactory, multiple instances can be created. Not like JUnit 5 which creates one per method.','One per method','One per suite'],answer:1,explanation:'TestNG default: one class instance shared across all @Test methods (unless parallel="instances"). JUnit 5 default: new instance per method. This means TestNG tests can share state via instance variables.'},
{id:1976,topic:'testng',difficulty:'intermediate',question:'What is `org.testng.ITestNGMethod` used for?',options:['A method wrapper','Represents a TestNG test method with metadata: getMethodName(), getGroups(), getDependsOnMethods(), getRealClass(), getInvocationCount()','A reflection wrapper','A test method factory'],answer:1,explanation:'ITestNGMethod is used in listeners and interceptors to inspect test metadata: method name, groups, dependencies, invocation count. Available via ITestResult.getMethod().'},
{id:1977,topic:'testng',difficulty:'advanced',question:'What is the TestNG `ISuite` interface?',options:['A suite configuration','Represents a running test suite with access to: getName(), getResults() (Map of test name to ISuiteResult), getAllMethods(), getParameter()','A suite runner','A suite configuration parser'],answer:1,explanation:'ISuite is available in ISuiteListener.onStart(ISuite) and onFinish(ISuite). getResults() gives per-test results. getSuiteState() gives overall state. Used for suite-level reporting.'},
{id:1978,topic:'testng',difficulty:'advanced',question:'What is `ISuiteResult` in TestNG?',options:['A single test result','Aggregates results for a single <test> element: getTestContext() which provides ITestContext with access to all passed/failed/skipped tests in that test','A suite summary','A suite runner result'],answer:1,explanation:'ISuiteResult wraps an ITestContext for a <test> section. suite.getResults().values() returns ISuiteResult objects. Each has getTestContext() for detailed results.'},
{id:1979,topic:'testng',difficulty:'intermediate',question:'What is the `configuration-failure-policy` attribute in testng.xml?',options:['Retry on config failure','Determines what happens when @Before/@After methods fail: "skip" (default) skips dependent tests; "continue" continues running tests despite configuration failures','A timeout policy','A class loading policy'],answer:1,explanation:'<suite configuration-failure-policy="continue"> keeps running tests even if @BeforeMethod/@BeforeClass fail. Default "skip" is usually safer to prevent cascading failures.'},
{id:1980,topic:'testng',difficulty:'advanced',question:'What is TestNG\'s support for annotations on test methods vs class level?',options:['Only method level','@Test on a CLASS marks all public methods as test methods. @Test on a METHOD marks only that method. Class-level @Test is overridden by method-level @Test for specific methods.','Only class level','Both levels with different precedence'],answer:1,explanation:'@Test on class: all public methods become tests. @Test(groups="smoke") on class applies to all methods. Method-level @Test overrides class-level for that specific method. Useful for mixin classes.'}
]);
